", \"name\": \"Moc zasilacza\", \"unit\": \"W\", \"values\": [\"180\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"180 W\"]}, {\"id\": \"201861\", \"name\": \"Komunikacja\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201861_32\"], \"valuesLabels\": [\"LAN 10/100/1000 Mbps\"]}, {\"id\": \"201865\", \"name\": \"System operacyjny\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201865_988427\"], \"valuesLabels\": [\"Windows 11 Professional\"]}, {\"id\": \"248819\", \"name\": \"Załączone wyposażenie\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"248819_952830\"], \"valuesLabels\": [\"inne\"]}, {\"id\": \"219805\", \"name\": \"Model procesora\", \"unit\": null, \"values\": [\"AMD Ryzen 5 PRO 2400G\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"AMD Ryzen 5 PRO 2400G\"]}, {\"id\": \"249393\", \"name\": \"Generacja procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"249393_1188963\"], \"valuesLabels\": [\"2\"]}, {\"id\": \"201817\", \"name\": \"Typ gniazda procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201817_209617\"], \"valuesLabels\": [\"Socket AM4\"]}, {\"id\": \"201721\", \"name\": \"Taktowanie maksymalne procesora\", \"unit\": \"GHz\", \"values\": [\"3.90\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"3,90 GHz\"]}, {\"id\": \"201729\", \"name\": \"Pamięć podręczna procesora\", \"unit\": \"MB\", \"values\": [\"4.00\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"4,00 MB\"]}, {\"id\": \"4329\", \"name\": \"Liczba rdzeni procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"4329_3\"], \"valuesLabels\": [\"4\"]}, {\"id\": \"201869\", \"name\": \"Liczba w