iesProduct\": true}, \"valuesLabels\": [\"3,80 GHz\"]}, {\"id\": \"201745\", \"name\": \"Typ pamięci RAM\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"201745_208893\"], \"valuesLabels\": [\"DDR4\"]}, {\"id\": \"200941\", \"name\": \"Wielkość pamięci RAM\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"200941_2205\"], \"valuesLabels\": [\"32 GB\"]}, {\"id\": \"201769\", \"name\": \"Typ dysku twardego\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"201769_208989\"], \"valuesLabels\": [\"SSD (M.2)\"]}, {\"id\": \"82\", \"name\": \"Pojemność dysku\", \"unit\": \"GB\", \"values\": [\"1000\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"1000 GB\"]}, {\"id\": \"249512\", \"name\": \"Kolor\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"249512_1647413\"], \"valuesLabels\": [\"czarny\"]}, {\"id\": \"201653\", \"name\": \"Typ komputera\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201653_208753\"], \"valuesLabels\": [\"komputer stacjonarny\"]}, {\"id\": \"224017\", \"name\": \"Kod producenta\", \"unit\": null, \"values\": [\"MG/KOMPUTER RYZEN7/1TB/32GB/VEGA8/W11\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"MG/KOMPUTER RYZEN7/1TB/32GB/VEGA8/W11\"]}, {\"id\": \"173\", \"name\": \"Monitor\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"173_1\"], \"valuesLabels\": [\"brak\"]}, {\"id\": \"174\", \"name\": \"Typ napędu\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"174_256\"], \"valuesLabels\": [\"brak\"]}, {\"id\": \"201861\", \"name\": \"Komunikacja\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201861_32\", \"201861_4096\"], \"valuesLabels\": [\"LAN 10/100/1000 Mbps\", \"Wi-Fi\"]}, {\"id\": \"201865\", \"name\": \"System operacyjny\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201865_1016326\"], \"valuesLabels\": [\"Windows 11\"]}, {\"id\": \"219805\", \"name\": \"Model procesora\", \"unit\": null, \"values\": [\"AMD Ryzen 7 5700G\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"AMD Ryzen 7 5700G\"]}, {\"id\": \"201817\", \"name\": \"Typ gniazda procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201817_209617\"], \"valuesLabels\": [\"Socket AM4\"]}, {\"id\": \"201721\", \"name\": \"Taktowanie maksymalne procesora\", \"unit\": \"GHz\", \"values\": [\"4.60\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"4,60 GHz\"]}, {\"id\": \"201729\", \"name\": \"Pamięć podręczna procesora\", \"unit\": \"MB\", \"values\": [\"20.00\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"20,00 MB\"]}, {\"id\": \"4329\", \"name\": \"Liczba rdzeni procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"4329_7\"], \"valuesLabels\": [\"8\"]}, {\"id\": \"201869\", \"name\": \"Liczba wątków procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201869_209837\"], \"valuesLabels\": [\"16\"]}, {\"id\": \"201753\", \"name\": \"Maksymalna pojemność pamięci RAM\", \"unit\": \"GB\", \"values\": [\"64\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"64 GB\"]}, {\"id\": \"201765\", \"name\": \"Liczba wszystkich slotów RAM\", \"unit\": null, \"values\": [\"2\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"2\"]}, {\"id\": \"201777\", \"name\": \"Interfejs dysku twardego\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201777_16\", \"201777_64\"], \"valuesLabels\": [\"M.2\", \"PCIe typ M.2\"]}, {\"id\": \"201785\", \"name\": \"Rodzaj karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201785_209021\"], \"valuesLabels\": [\"zintegrowana\"]}, {\"id\": \"201789\", \"name\": \"Producent karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201789_720487\"], \"valuesLabels\": [\"AMD\"]}, {\"id\": \"250525\", \"name\": \"Chipset karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"250525_1927470\"], \"valuesLabels\": [\"AMD Radeon Vega 8\"]}, {\"id\": \"200937\", \"name\": \"Pamięć karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"200937_2145\"], \"valuesLabels\": [\"współdzielona\"]}, {\"id\": \"201801\", \"name\": \"Złącza karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201801_8\", \"201801_32\", \"201801_512\"], \"valuesLabels\": [\"DVI-D\", \"HDMI\", \"VGA (D-Sub)\"]}, {\"id\": \"219813\", \"name\": \"Model płyty głównej\", \"unit\": null, \"values\": [\"B450\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"B450\"]}, {\"id\": \"201821\", \"name\": \"Gniazda rozszerzeń\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201821_4194304\", \"201821_16384\", \"201821_8192\", \"201821_1048576\"], \"valuesLabels\": [\"M.2\", \"PCIe 3.0/2.0 x1\", \"PCIe 3.0 x16\", \"SATA III (6 GB/s)\"]}, {\"id\": \"201833\", \"name\": \"Chipset płyty głównej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201833_561673\"], \"valuesLabels\": [\"AMD B450\"]}, {\"id\": \"201825\", \"name\": \"Złącza zewnętrzne płyty głównej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201825_32768\", \"201825_512\", \"201825_64\", \"201825_256\", \"201825_128\", \"201825_1\", \"201825_8\", \"201825_2048\"], \"valuesLabels\": [\"DVi-D\", \"HDMI\", \"mini jack 3,5 (audio)\", \"PS/2\", \"RJ45\", \"USB 2.0 typ A\", \"USB 3.1 typ A gen 1\", \"VGA (D-Sub)\"]}, {\"id\": \"4477\", \"name\": \"Typ obudowy\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"4477_40\"], \"valuesLabels\": [\"Midi Tower\"]}, {\"id\": \"201845\", \"name\": \"Złącza obudowy\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201845_16\", \"201845_1\", \"201845_2\"], \"valuesLabels\": [\"mini jack 3,5 (audio)\", \"USB 2.0 typ A\", \"USB 3.0 typ A\"]}], \"description\": {\"sections\": [{\"items\": [{\"type\": \"TEXT\", \"content\": \"<h2>▶️SZYBKI KOMPUTER GAMINGOWY AMD RYZEN 7 5700G 32GB 1TB NVME RX VEGA 8 WIN 11 WIFI ◀️</h2>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p>⭐ Nowoczesna jednostka komputerowa zaprojektowana z myślą o użytkownikach poszukujących&nbsp;<b>balansu między wysoką mocą obliczeniową a stabilnością pracy.</b> Konfiguracja oparta na 8-rdzeniowym procesorze AMD Ryzen 7 5700G oraz 32GB pamięci RAM zapewnia <b>błyskawiczną reakcję systemu i płynną obsługę wymagających aplikacji.</b></p> <p>Zestaw bazuje wyłącznie na <b>markowych podzespołach</b> uznanych producentów (AMD, ASRock, Hynix, SiliconPower). Każdy egzemplarz przechodzi rygorystyczny <b>proces weryfikacji oraz testy obciążeniowe</b>, co gwarantuje niezawodność i pełną gotowość do pracy bezpośrednio po wyjęciu z pudełka. Dzięki solidnemu zasilaczowi oraz gamingowej obudowie z wydajną cyrkulacją powietrza, komputer stanowi idealną bazę pod przyszłą rozbudowę o dedykowaną kartę graficzną.</p> <h2>✅ Możliwe zastosowania zestawu:</h2> <ul> <li><b>Gaming e-sportowy:</b> Płynna rozgrywka w popularnych tytułach sieciowych, takich jak Counter-Strike 2, League of Legends, Valorant czy Minecraft.</li> <li><b>Zaawansowana praca biurowa:</b> Bezproblemowa obsługa wielu procesów jednocześnie, praca na dużych bazach danych i arkuszach kalkulacyjnych.</li> <li><b>Multimedia i edukacja:</b> Obsługa aplikacji VOD w wysokiej rozdzielczości, szybkie przeglądanie sieci oraz stabilna praca w aplikacjach edukacyjnych.</li> </ul>\"}, {\"url\": \"https://a.allegroimg.com/original/1168fa/5186dec04fd3aa4d9f7becad3b75\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h2>↘️ Najważniejsze parametry:</h2> <ul> <li><b>Procesor AMD Ryzen 7 5700G</b> - 8 rdzeni /16 wątków / Taktowanie do 4,6Ghz / 20MB SmartCache</li> <li><b>Chłodzenie procesora - AMD Wraith Stealth</b>&nbsp;- 95 mm</li> <li><b>Płyta główna ASRock B450M-HDV R4.0</b> - Slot M.2 NVMe / Obsługa do 64GB RAM DDR4 / Porty USB 3.1 Gen1</li> <li><b>Pamięć operacyjna Hynix RAM DDR4 32GB (2x16GB)</b></li> <li><b>Karta Graficzna AMD Radeon Vega 8</b>&nbsp;- 8 rdzeni / Taktowanie 2000MHz</li> <li><b>Dysk SSD SiliconPower 1TB M.2 NVMe</b> - do 5x szybszy od standardowych dysków SSD / do 25x szybszy od dysków HDD</li> <li><b>Obudowa AeroCool Volcan RGB</b> - Świecąca gamingowa obudowa RGB / Przeźroczysty panel boczny / Świetny przepływ powietrza</li> <li><b>Zasilacz Tacens Anima 550W 80 Plus Bronze</b></li> <li><b>System operacyjny Windows 11 Home</b> - Dożywotnia licencja</li> <li><b>Karta sieciowa Tenda Wi-Fi 6 na USB</b> - Bezprzewodowa praca b/g/n/ac/ax do 300 Mb/s</li> </ul>\"}, {\"url\": \"https://a.allegroimg.com/original/11fbc1/2177611440179bd4cf0a02b522af\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h2>⚙️OPIS PODZESPOŁÓW</h2>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>⭐Procesor AMD Ryzen 7 5700G</b></p> <p>Wydajna jednostka najnowszej generacji – 8 rdzeni i 16 wątków o taktowaniu do 4.6 GHz. Dzięki 20 MB SmartCache gwarantuje błyskawiczne działanie systemu, aplikacji oraz doskonałą wielozadaniowość. Idealny do pracy i rozrywki.</p> <p><b>⭐Pamięć RAM SK Hynix DDR4 32GB (2x16GB)</b></p> <p>Zainstalowane 32GB szybkiej pamięci DDR4 w dwóch kościach (2x16GB) o wysokim taktowaniu i niskim opóźnieniu. Idealne rozwiązanie do wymagających aplikacji i pracy wielozadaniowej.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/11cd09/c22c4aa44d74ab60f0a7af8fd78f\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>⭐Zintegrowana grafika AMD Radeon Vega 8</b></p> <p>Wydajna zintegrowana karta graficzna z 8 rdzeniami GPU taktowanymi na 2000 MHz. Umożliwia rozgrywkę w popularne gry e-sportowe oraz sprawne działanie przy pracy graficznej i multimedialnej.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/113dbd/8069c386486788000e5742ff2dd8\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>⭐Dysk SSD SiliconPower 1TB M.2 NVMe</b></p> <p>Superszybki dysk SSD o pojemności 1TB w formacie M.2 z interfejsem NVMe PCI-e 4.0. Do 5 razy szybszy od zwykłych SSD i aż 25 razy szybszy od klasycznego dysku HDD. System i aplikacje uruchamiają się błyskawicznie.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/115e5d/8587b0b74a9f94cc1abffe98f4ad\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>⭐Chłodzenie AMD Stealth</b></p> <p>Zamontowane chłodzenie <b>AMD Wraith Stealth</b> z wentylatorem <b>95 mm</b> zapewnia stabilne temperatury i cichą pracę procesora nawet podczas intensywnego grania. Sprawdzone, fabryczne rozwiązanie AMD – gotowe do gry od razu po uruchomieniu.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/1140fc/785d52f8453e8d53f46fcf8f81ba\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>⭐Płyta główna AsRock B450-HDV R4.0</b></p> <p>Płyta główna <b>ASRock B450-HDV R4.0</b> oparta na chipsecie B450, wyposażona w <b>slot M.2 (NVMe)</b> dla szybkich dysków SSD oraz <b>porty SATA</b> na dodatkowe nośniki. Stabilna konstrukcja, pełna kompatybilność z procesorami AMD Ryzen i wszystko, czego potrzeba do solidnego komputera gamingowego.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/1170bd/2317bdd940868e52e85c959b3680\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>⭐Zasilacz Tacens Anima 550W</b></p> <p>Lekki i wydajny zasilacz ATX o mocy <b>550 W</b>, idealny do zestawów komputerowych, w tym gamingowych. Model posiada <b>certyfikat 80 PLUS Bronze</b>, który zapewnia dobrą sprawność energetyczną i mniejsze zużycie prądu w porównaniu z podstawowymi jednostkami bez certyfikatu.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/11087c/3e438f14482cb730755c05cde09f\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>⭐️Obudowa AeroCool Volcan RGB</b></p> <p>Stylowa, nowoczesna obudowa z podświetleniem RGB i przeszklonym panelem bocznym, wydajnym i cichym zasilaczem zapewnia stabilną pracę całego zestawu komputerowego. Wyposażona w wentylatory z podświetleniem FRGB. Świetnie wygląda i zapewnia dobry przepływ powietrza.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/114504/c24550014d53af9ac380521dcbf8\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h1>✅ Oprogramowanie biurowe oraz użytkowe</h1> <ul> <li><b>VLC Media Player</b> – Uniwersalny odtwarzacz multimedialny, który obsługuje niemal każdy format wideo i audio.</li> <li><b>WinRAR</b> – Popularny program do kompresji i dekompresji plików, wspierający formaty RAR, ZIP oraz wiele innych.</li> <li><b>Adobe Acrobat Reader</b> – Najczęściej używany program do wyświetlania, drukowania i komentowania plików PDF.</li> </ul> <h1>✅&nbsp;Windows 11 zawsze aktualny i zabezpieczony</h1> <ul> <li><b>Bezpieczeństwo bez opłat:</b> Zapomnij o kupowaniu dodatkowych antywirusów. System posiada zintegrowany pakiet <b>Microsoft Defender</b>, który chroni Twoje pliki, hasła i tożsamość w sieci 24/7.</li> <li><b>Szybkość i stabilność:</b> Windows 11 został zoptymalizowany pod kątem oszczędzania energii i szybszego wybudzania, co przekłada się na dłuższą pracę na baterii i płynne działanie aplikacji.</li> <li><b>Nowoczesny wygląd:</b> Odświeżone menu Start i elegancki design sprawiają, że korzystanie z komputera to czysta przyjemność.</li> </ul>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h1>✅Filtr przeciwkurzowy</h1> <p>Często komputer po niedługim czasie od zakupu zaczyna mieć wyższe temperatury na podzespołach, dzieje się tak przez osiadający na nich kurz. Z tym komputerem nie musisz się o to martwić! Obudowa posiada filtry przeciwkurzowe, dzięki którym utrzymany jest porządek wewnątrz obudowy i nie ma mowy o wyższych temperaturach!</p>\"}, {\"url\": \"https://a.allegroimg.com/original/115848/1f3cc34040d4bb3f7f799fd7bf70\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h1>⬇️Przykładowa wydajność w grach</h1>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h1>✔️Fortnite</h1> <h2>➡️ Rozdzielczość 1920x1080, ustawienia graficzne niskie</h2> <p><b>Średnia liczba klatek: 71FPS</b></p> <h1>✔️GTA 5</h1> <h2>➡️ Rozdzielczość 1920x1080, ustawienia graficzne średnio/wysokie</h2> <p><b>Średnia liczba klatek: 61FPS</b></p>\"}, {\"url\": \"https://a.allegroimg.com/original/11842d/9b88bb7c41579655c1f7003639be\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h1>✔️Counter-Strike 2</h1> <h2>➡️ Rozdzielczość 1920x1080, ustawienia graficzne niskie</h2> <p><b>Średnia liczba klatek: 71FPS</b></p> <h1>✔️Valorant</h1> <h2>➡️ Rozdzielczość 1920x1080, ustawienia graficzne niskie</h2> <p><b>Średnia liczba klatek: 200FPS</b></p>\"}, {\"url\": \"https://a.allegroimg.com/original/11311a/68d280df4f9892e942bbb63803b3\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h2>⬇️Zdjęcia przykładowej sztuki</h2> <p>Dzięki temu jesteś w stanie zobaczyć jak będzie wyglądał twój nowy sprzęt. Staramy się jak najbardziej odzwierciedlić stan sprzętu.</p>\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/110124/abe63f6f452e8e59aaab4c8d3e9a\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/11b46d/80f9207045a78446a84acc7f0b15\", \"type\": \"IMAGE\"}]}]}, \"publication\": {\"status\": \"LISTED\"}, \"productSafety\": {\"safetyInformation\": {\"type\": \"TEXT\", \"description\": \"Lista ostrzeżeń dotyczących bezpieczeństwa komputerów stacjonarnych oparta o wymagania Rozporządzenia (UE) 2023/988 w sprawie ogólnego bezpieczeństwa produktów (GPSR)\\n\\n*   Ryzyko porażenia prądem:\\n\\n    *   Upewnij się, że komputer jest podłączony do sprawnego gniazdka z uziemieniem.\\n    *   Nie dotykaj wtyczki ani kabla mokrymi rękami.\\n    *   Unikaj używania komputera w miejscach o dużej wilgotności.\\n*   Ryzyko przegrzania:\\n\\n    *   Zapewnij odpowiednią wentylację, zachowując co najmniej 5 cm wolnej przestrzeni wokół komputera.\\n    *   Nie blokuj otworów wentylacyjnych.\\n*   Ryzyko pożaru:\\n\\n    *   Używaj wyłącznie oryginalnych ładowarek i akcesoriów zalecanych przez producenta.\\n    *   Nie pozostawiaj komputera włączonego bez nadzoru w pobliżu materiałów łatwopalnych.\\n*   Ryzyko uszkodzeń ciała:\\n\\n    *   Używaj komputera na stabilnej powierzchni, aby zminimalizować ryzyko upadku.\\n*   Zagrożenia w wilgotnym środowisku:\\n\\n    *   Nie używaj komputera na zewnątrz podczas deszczu ani w miejscach o dużej wilgotności.\\n    *   W przypadku zalania komputera natychmiast odłącz go od źródła zasilania i skontaktuj się z serwisem.\\n*   Zagrożenia w wysokich temperaturach:\\n\\n    *   Nie eksponuj komputera na bezpośrednie działanie promieni słonecznych.\\n    *   Unikaj korzystania z komputera w temperaturach przekraczających zalecany zakres (zwykle 5-35°C).\\n*   Ryzyko uszkodzenia podczas czyszczenia:\\n\\n    *   Przed czyszczeniem odłącz komputer od zasilania i użyj miękkiej, lekko wilgotnej ściereczki.\\n    *   Unikaj stosowania silnych detergentów mogących uszkodzić powierzchnię komputera.\\n*   Ostrożność podczas wymiany akcesoriów:\\n\\n    *   Korzystaj wyłącznie z akcesoriów zalecanych przez producenta.\\n    *   W przypadku wymiany baterii, przestrzegaj zaleceń producenta i nie wystawiaj baterii na działanie wysokich temperatur.\\n*   Zagrożenia związane z użytkowaniem baterii:\\n\\n    *   Unikaj uszkodzenia baterii przez uderzenia lub jej przebicie.\\n    *   Jeśli bateria się przegrzewa lub puchnie, natychmiast przerwij użytkowanie komputera.\\n*   Ostrzeżenia dotyczące dzieci:\\n\\n    *   Trzymaj kable zasilające poza zasięgiem dzieci.\\n    *   Upewnij się, że dzieci nie bawią się komputerem ani akcesoriami, które mogą być niebezpieczne.\"}, \"responsibleProducers\": []}, \"trustedContent\": {\"paths\": [], \"productPaths\": []}, \"hasProtectedBrand\": false, \"aiCoCreatedContent\": {\"paths\": []}}','Komputery stacjonarne','MOBIKOMP','MG/KOMPUTER RYZEN7/1TB/32GB/VEGA8/W11'),(1177,'1cef7185-e35d-4615-b26f-271930600de0',1053.00,33,'2023-03-06 05:09:04','{\"id\": \"1cef7185-e35d-4615-b26f-271930600de0\", \"name\": \"MINI KOMPUTER DELL 3040 Micro i3 6GEN 8GB 128GB SSD HDMI WiFi W11\", \"price\": 1053, \"stock\": 33, \"images\": [{\"url\": \"https://a.allegroimg.com/original/11aa35/2b2112a34e229709c4da6e93e8d8\"}, {\"url\": \"https://a.allegroimg.com/original/110789/364af83a442b818e00e143ceb606\"}, {\"url\": \"https://a.allegroimg.com/original/11657e/e455bc7a4ca9b11b3da0b2813300\"}, {\"url\": \"https://a.allegroimg.com/original/11de9f/ef08901443f7883ae20a9cad29c5\"}, {\"url\": \"https://a.allegroimg.com/original/113b6d/f862c25c45d4aa00b8c6fd6a4e42\"}, {\"url\": \"https://a.allegroimg.com/original/118c6b/571be2ac479ea2e65c68483140b0\"}, {\"url\": \"https://a.allegroimg.com/original/11d691/078aa2ce416994994c8f2c2ad7dd\"}, {\"url\": \"https://a.allegroimg.com/original/11518a/70ee79c04e70aea0880c86e0bace\"}, {\"url\": \"https://a.allegroimg.com/original/11bcc6/d684d2784fa4b644bb0098bc1aef\"}, {\"url\": \"https://a.allegroimg.com/original/110e58/bcf21b55481c81818c113efd870f\"}, {\"url\": \"https://a.allegroimg.com/original/114e6f/8ed85646448599c2ed9796b5cb9f\"}, {\"url\": \"https://a.allegroimg.com/original/118266/1ff8b7974276ba6fc0e6127f7c9c\"}, {\"url\": \"https://a.allegroimg.com/original/11d43d/3756e0a9406baf6fca8352c7ffab\"}], \"category\": {\"id\": \"486\", \"path\": [{\"id\": \"954b95b6-43cf-4104-8354-dea4d9b10ddf\", \"name\": \"Allegro\"}, {\"id\": \"42540aec-367a-4e5e-b411-17c09b08e41f\", \"name\": \"Elektronika\"}, {\"id\": \"2\", \"name\": \"Komputery\"}, {\"id\": \"486\", \"name\": \"Komputery stacjonarne\"}], \"similar\": []}, \"createdAt\": \"2023-03-06T04:09:03.800Z\", \"parameters\": [{\"id\": \"248811\", \"name\": \"Marka\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"248811_1131529\"], \"valuesLabels\": [\"Dell\"]}, {\"id\": \"237206\", \"name\": \"Model\", \"unit\": null, \"values\": [\"3040 Micro i3-6GEN SSD HDMI WiFi W11H\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"3040 Micro i3-6GEN SSD HDMI WiFi W11H\"]}, {\"id\": \"206182\", \"name\": \"Seria\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"206182_226294\"], \"valuesLabels\": [\"Intel Core i3\"]}, {\"id\": \"201725\", \"name\": \"Taktowanie bazowe procesora\", \"unit\": \"GHz\", \"values\": [\"3.20\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"3,20 GHz\"]}, {\"id\": \"201745\", \"name\": \"Typ pamięci RAM\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"201745_208889\"], \"valuesLabels\": [\"DDR3L\"]}, {\"id\": \"200941\", \"name\": \"Wielkość pamięci RAM\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"200941_2185\"], \"valuesLabels\": [\"8 GB\"]}, {\"id\": \"201769\", \"name\": \"Typ dysku twardego\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"201769_208985\"], \"valuesLabels\": [\"SSD\"]}, {\"id\": \"82\", \"name\": \"Pojemność dysku\", \"unit\": \"GB\", \"values\": [\"128\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"128 GB\"]}, {\"id\": \"249512\", \"name\": \"Kolor\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"249512_1647413\"], \"valuesLabels\": [\"czarny\"]}, {\"id\": \"201653\", \"name\": \"Typ komputera\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201653_208757\"], \"valuesLabels\": [\"komputer mini PC\"]}, {\"id\": \"224017\", \"name\": \"Kod producenta\", \"unit\": null, \"values\": [\"3040 Micro i3-6GEN SSD HDMI WiFi W11H\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"3040 Micro i3-6GEN SSD HDMI WiFi W11H\"]}, {\"id\": \"173\", \"name\": \"Monitor\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"173_1\"], \"valuesLabels\": [\"brak\"]}, {\"id\": \"174\", \"name\": \"Typ napędu\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"174_256\"], \"valuesLabels\": [\"brak\"]}, {\"id\": \"201861\", \"name\": \"Komunikacja\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201861_32\", \"201861_4096\"], \"valuesLabels\": [\"LAN 10/100/1000 Mbps\", \"Wi-Fi\"]}, {\"id\": \"201865\", \"name\": \"System operacyjny\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201865_988426\"], \"valuesLabels\": [\"Windows 11 Home\"]}, {\"id\": \"248819\", \"name\": \"Załączone wyposażenie\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"248819_952831\"], \"valuesLabels\": [\"brak\"]}, {\"id\": \"219805\", \"name\": \"Model procesora\", \"unit\": null, \"values\": [\"Intel Core i3-6100T\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"Intel Core i3-6100T\"]}, {\"id\": \"249393\", \"name\": \"Generacja procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"249393_1188967\"], \"valuesLabels\": [\"6\"]}, {\"id\": \"201817\", \"name\": \"Typ gniazda procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201817_209581\"], \"valuesLabels\": [\"Socket 1151\"]}, {\"id\": \"201721\", \"name\": \"Taktowanie maksymalne procesora\", \"unit\": \"GHz\", \"values\": [\"3.20\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"3,20 GHz\"]}, {\"id\": \"201729\", \"name\": \"Pamięć podręczna procesora\", \"unit\": \"MB\", \"values\": [\"3.00\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"3,00 MB\"]}, {\"id\": \"4329\", \"name\": \"Liczba rdzeni procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"4329_2\"], \"valuesLabels\": [\"2\"]}, {\"id\": \"201869\", \"name\": \"Liczba wątków procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201869_209825\"], \"valuesLabels\": [\"4\"]}, {\"id\": \"201749\", \"name\": \"Taktowanie szyny pamięci RAM\", \"unit\": \"MHz\", \"values\": [\"1600\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"1600 MHz\"]}, {\"id\": \"201777\", \"name\": \"Interfejs dysku twardego\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201777_1\"], \"valuesLabels\": [\"SATA III\"]}, {\"id\": \"201785\", \"name\": \"Rodzaj karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201785_209021\"], \"valuesLabels\": [\"zintegrowana\"]}, {\"id\": \"201789\", \"name\": \"Producent karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201789_209029\"], \"valuesLabels\": [\"Intel\"]}, {\"id\": \"250525\", \"name\": \"Chipset karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"250525_1927521\"], \"valuesLabels\": [\"Intel HD Graphics 530\"]}, {\"id\": \"201809\", \"name\": \"Producent płyty głównej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201809_720935\"], \"valuesLabels\": [\"Dell\"]}, {\"id\": \"201825\", \"name\": \"Złącza zewnętrzne płyty głównej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201825_4096\", \"201825_512\", \"201825_128\", \"201825_1\", \"201825_4\"], \"valuesLabels\": [\"DisplayPort\", \"HDMI\", \"RJ45\", \"USB 2.0 typ A\", \"USB 3.0 typ A\"]}, {\"id\": \"4477\", \"name\": \"Typ obudowy\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"4477_209773\"], \"valuesLabels\": [\"Mini PC\"]}, {\"id\": \"201845\", \"name\": \"Złącza obudowy\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201845_16\", \"201845_2\"], \"valuesLabels\": [\"mini jack 3,5 (audio)\", \"USB 3.0 typ A\"]}], \"description\": {\"sections\": [{\"items\": [{\"type\": \"TEXT\", \"content\": \"<h1>Dell OptiPlex 3040 Micro</h1> <ul> <li><b>Procesor:</b> Intel® Core™ i3-6100T (3 MB, do 3,20 GHz)</li> <li><b>Pamięć RAM: </b>8 GB</li> <li><b>Dysk twardy: </b>128 GB SSD</li> </ul>\"}, {\"url\": \"https://a.allegroimg.com/original/11aa35/2b2112a34e229709c4da6e93e8d8\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>Dell OptiPlex 3040 Tiny</b> to doskonały wybór dla osób poszukujących kompaktowego i niezawodnego komputera do codziennej pracy. Model ten wyposażony jest w procesor <b>Intel Core i3 szóstej generacji</b>, pamięć <b>RAM DDR3L</b> oraz szybki <b>dysk SSD</b>, co zapewnia płynne działanie systemu i aplikacji biurowych. Komputer świetnie sprawdzi się podczas przeglądania internetu, pracy z dokumentami, nauki zdalnej oraz innych podstawowych zadań. Niewielkie rozmiary obudowy typu Tiny pozwalają zaoszczędzić miejsce na biurku i łatwo dopasować urządzenie do każdej przestrzeni. Dzięki solidnemu wykonaniu i sprawdzonym rozwiązaniom marki Dell, <b>OptiPlex 3040 Tiny</b> to praktyczny i trwały wybór do domu lub biura.</p>\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/11d43d/3756e0a9406baf6fca8352c7ffab\", \"type\": \"IMAGE\"}, {\"type\": \"TEXT\", \"content\": \"<p><b>Windows 11</b>&nbsp;- najlepszy system operacyjny na rynku. Dzięki szybkości i przejrzystości interfejsu użytkownika, będziesz mógł łatwo dostosować funkcje do swoich potrzeb. System automatycznie aktualizuje sterowniki, co pozwala zaoszczędzić czas i energię.</p> <p>Skuteczna ochrona:&nbsp;<b>Microsoft Defender</b>&nbsp;wykrywa i usuwa szkodliwe oprogramowanie, zapewniając maksymalne bezpieczeństwo Twojemu komputerowi. Dzięki stałym aktualizacjom bazy wirusów, program jest w stanie wykryć nawet najnowsze zagrożenia.</p> <p>Łatwość użytkowania: Program&nbsp;<b>Microsoft Defender</b>&nbsp;jest łatwy w obsłudze i nie wymaga skomplikowanej konfiguracji. Możesz skoncentrować się na swojej pracy, a program zadba o bezpieczeństwo Twojego komputera.</p> <p>Wsparcie dla innych narzędzi zabezpieczających:&nbsp;<b>Microsoft Defender</b>&nbsp;może współpracować z innymi programami antywirusowymi, dzięki czemu zapewniasz sobie dodatkową warstwę ochrony.</p> <p>Darmowy i wbudowany w system:&nbsp;<b>Microsoft Defender</b>&nbsp;jest darmowym oprogramowaniem, które jest już zainstalowane na Twoim komputerze, gdy używasz systemu Windows. Nie musisz martwić się o dodatkowe koszty, a jednocześnie masz pewność, że Twój komputer jest chroniony.</p> <p>Dzięki programowi&nbsp;<b>Microsoft Defender</b>, możesz mieć pewność, że Twoje dane są bezpieczne, a Ty możesz skupić się na swojej pracy lub rozrywce bez obaw o wirusy i inne zagrożenia.</p> <p><b>OpenOffice</b>&nbsp;to pakiet biurowy, który pozwoli Ci na tworzenie profesjonalnych dokumentów, arkuszy kalkulacyjnych i prezentacji.</p> <p><b>OpenOffice</b>&nbsp;zawiera wiele modułów, takich jak:</p> <p><b>Writer</b>: moduł do tworzenia tekstu, odpowiednik Microsoft Word,</p> <p><b>Calc</b>: moduł do tworzenia arkuszy kalkulacyjnych, odpowiednik Microsoft Excel,</p> <p><b>Impress</b>: moduł do tworzenia prezentacji, odpowiednik Microsoft PowerPoint,</p> <p><b>Draw</b>: moduł do tworzenia grafik wektorowych, rysowania i diagramów,</p> <p><b>Base</b>: moduł do tworzenia i zarządzania bazami danych.</p> <p>Program&nbsp;<b>OpenOffice</b>&nbsp;oferuje wiele zalet, takich jak:</p> <p><b>OpenOffice</b>&nbsp;jest w pełni kompatybilny z innymi pakietami biurowymi, w tym z Microsoft Office, co oznacza, że nie będziesz miał problemów z otwieraniem i edycją dokumentów utworzonych w innych programach.</p> <p>Interfejs&nbsp;<b>OpenOffice</b>&nbsp;jest intuicyjny i łatwy w obsłudze, dzięki czemu możesz skoncentrować się na tworzeniu swoich dokumentów zamiast na nauce obsługi skomplikowanego oprogramowania.</p>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>Procesor Intel Core i3-6100T</b></p> <p>Procesory Core i3 zwiększają dynamikę działania, spełniają potrzeby użytkowników w zakresie mocy i szybkości. Zapewniają szybkie otwieranie plików i programów oraz bezproblemowe błyskawiczne przełączanie pomiędzy aplikacjami i stronami internetowymi. Dają nadzwyczajne możliwości obsługi rozrywki oraz płynne odtwarzanie filmów w dużej rozdzielczości.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/114e6f/8ed85646448599c2ed9796b5cb9f\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/118266/1ff8b7974276ba6fc0e6127f7c9c\", \"type\": \"IMAGE\"}, {\"type\": \"TEXT\", \"content\": \"<p><b>Szybki dysk SSD</b></p> <p><b>Dysk SSD - Solid State Drive</b>&nbsp;to rozwiązanie, które ożywi Twój komputer. Szybkość i niezawodność to tylko część korzyści, jakie oferuje półprzewodnikowy nośnik danych. Dzięki brakowi ruchomych części, SSD cechują się znacznie krótszym czasem dostępu do danych, cichą pracą i dużą odpornością na uszkodzenia mechaniczne. To idealne rozwiązanie dla osób, które potrzebują wydajnego sprzętu do pracy lub rozrywki.</p>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p><b>Karta graficzna Intel HD Graphics 530</b></p> <p>Technologia Intel HD Graphics zapewnia wyjątkową jakość obrazu, zarówno podczas grania w gry, edycji wideo czy oglądania filmów. Doskonały wybór dla użytkowników ceniących sobie wysokiej jakości wrażenia wizualne.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/110e58/bcf21b55481c81818c113efd870f\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/11518a/70ee79c04e70aea0880c86e0bace\", \"type\": \"IMAGE\"}, {\"type\": \"TEXT\", \"content\": \"<h2>Nieograniczone możliwości multimedialne są na wyciągnięcie Twojej ręki!</h2> <p>Komputer idealnie nadaje się również do wszelkich multimediów.</p>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p>Nie chcesz inwestować w drogi sprzęt, ale masz ochotę zagrać w najnowsze gry? Mamy dla Ciebie rozwiązanie! Nasz sprzęt z usługą <b>GeForce Now</b>&nbsp;to idealna propozycja dla każdego fana gier. Dzięki aplikacji&nbsp;<b>GeForce Now</b>, nie potrzebujesz już potężnego komputera, aby cieszyć się najbardziej wymagającymi grami. Wszystko, czego potrzebujesz, to stabilne połączenie z internetem. Zamów już dziś i graj w swoje ulubione gry w dowolnym miejscu i czasie! Przekonaj się, że gra w chmurze może dostarczyć niezapomniane wrażenia podczas rozgrywek, bez względu na to, gdzie się znajdujesz.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/11d691/078aa2ce416994994c8f2c2ad7dd\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/110789/364af83a442b818e00e143ceb606\", \"type\": \"IMAGE\"}, {\"type\": \"TEXT\", \"content\": \"<h2>SPECYFIKACJA</h2> <ul> <li><b>Producent:</b> Dell</li> <li><b>Model: </b>Optiplex 3040 Micro</li> <li><b>Procesor:</b> Intel® Core™ i3-6100T (3 MB, do 3,20 GHz)</li> <li><b>Pamięć RAM:</b> 8 GB DDR3L</li> <li><b>Dysk twardy:</b> 128 GB SSD</li> <li><b>Grafika:</b> Intel HD Graphics 530</li> <li><b>Karta dźwiękowa:</b> Zintegrowana HD Audio</li> <li><b>Komunikacja :</b> LAN 10/100/1000, Wi-Fi</li> <li><b>System:</b> Windows 10 Home</li> <li><b>Porty:</b> USB 2.0 typ A, USB 3.0 typ A, mini jack 3,5 (audio), RJ45, HDMI, DisplayPort</li> <li><b>Informacje dodatkowe:</b> zasilacz oraz antenka Wi-Fi w zestawie</li> </ul>\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/11657e/e455bc7a4ca9b11b3da0b2813300\", \"type\": \"IMAGE\"}, {\"url\": \"https://a.allegroimg.com/original/11de9f/ef08901443f7883ae20a9cad29c5\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/113b6d/f862c25c45d4aa00b8c6fd6a4e42\", \"type\": \"IMAGE\"}, {\"url\": \"https://a.allegroimg.com/original/118c6b/571be2ac479ea2e65c68483140b0\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<h2>Bezpieczne pakowanie</h2> <p>Dlatego nasze komputery są starannie pakowane w dedykowane opakowania i mocne kartony, oznaczone naklejkami ostrzegawczymi dla kurierów.</p>\"}, {\"url\": \"https://a.allegroimg.com/original/11bcc6/d684d2784fa4b644bb0098bc1aef\", \"type\": \"IMAGE\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p>✔️ Komputer posiada aktualny system operacyjny, najnowsze sterowniki oraz jest gotowy do natychmiastowej pracy po rozpakowaniu.</p> <p>✔️ Gwarantujemy wybór niezawodnego sprzętu, na którym możesz polegać.</p> <p>Dzięki temu, że wybierasz używany sprzęt, pomagasz zmniejszyć ilość odpadów elektronicznych i chronisz naszą planetę.</p>\"}]}, {\"items\": [{\"type\": \"TEXT\", \"content\": \"<p>Komputery używane, dokładnie przetestowane i 100% sprawne technicznie. Gotowe do pracy.</p>\"}]}]}, \"publication\": {\"status\": \"LISTED\"}, \"productSafety\": {\"safetyInformation\": {\"type\": \"TEXT\", \"description\": \"Lista ostrzeżeń dotyczących bezpieczeństwa komputerów stacjonarnych oparta o wymagania Rozporządzenia (UE) 2023/988 w sprawie ogólnego bezpieczeństwa produktów (GPSR)\\n\\n*   Ryzyko porażenia prądem:\\n\\n    *   Upewnij się, że komputer jest podłączony do sprawnego gniazdka z uziemieniem.\\n    *   Nie dotykaj wtyczki ani kabla mokrymi rękami.\\n    *   Unikaj używania komputera w miejscach o dużej wilgotności.\\n*   Ryzyko przegrzania:\\n\\n    *   Zapewnij odpowiednią wentylację, zachowując co najmniej 5 cm wolnej przestrzeni wokół komputera.\\n    *   Nie blokuj otworów wentylacyjnych.\\n*   Ryzyko pożaru:\\n\\n    *   Używaj wyłącznie oryginalnych ładowarek i akcesoriów zalecanych przez producenta.\\n    *   Nie pozostawiaj komputera włączonego bez nadzoru w pobliżu materiałów łatwopalnych.\\n*   Ryzyko uszkodzeń ciała:\\n\\n    *   Używaj komputera na stabilnej powierzchni, aby zminimalizować ryzyko upadku.\\n*   Zagrożenia w wilgotnym środowisku:\\n\\n    *   Nie używaj komputera na zewnątrz podczas deszczu ani w miejscach o dużej wilgotności.\\n    *   W przypadku zalania komputera natychmiast odłącz go od źródła zasilania i skontaktuj się z serwisem.\\n*   Zagrożenia w wysokich temperaturach:\\n\\n    *   Nie eksponuj komputera na bezpośrednie działanie promieni słonecznych.\\n    *   Unikaj korzystania z komputera w temperaturach przekraczających zalecany zakres (zwykle 5-35°C).\\n*   Ryzyko uszkodzenia podczas czyszczenia:\\n\\n    *   Przed czyszczeniem odłącz komputer od zasilania i użyj miękkiej, lekko wilgotnej ściereczki.\\n    *   Unikaj stosowania silnych detergentów mogących uszkodzić powierzchnię komputera.\\n*   Ostrożność podczas wymiany akcesoriów:\\n\\n    *   Korzystaj wyłącznie z akcesoriów zalecanych przez producenta.\\n    *   W przypadku wymiany baterii, przestrzegaj zaleceń producenta i nie wystawiaj baterii na działanie wysokich temperatur.\\n*   Zagrożenia związane z użytkowaniem baterii:\\n\\n    *   Unikaj uszkodzenia baterii przez uderzenia lub jej przebicie.\\n    *   Jeśli bateria się przegrzewa lub puchnie, natychmiast przerwij użytkowanie komputera.\\n*   Ostrzeżenia dotyczące dzieci:\\n\\n    *   Trzymaj kable zasilające poza zasięgiem dzieci.\\n    *   Upewnij się, że dzieci nie bawią się komputerem ani akcesoriami, które mogą być niebezpieczne.\"}, \"responsibleProducers\": [{\"id\": \"5a19885c-b071-408d-9c12-19f29b22e854\", \"name\": \"Dell.\", \"producerData\": {\"address\": {\"city\": \"Warszawa\", \"street\": \"ul. Domaniewska 48\", \"postalCode\": \"02-672\", \"countryCode\": \"PL\"}, \"contact\": {\"email\": \"pl_customercare@dell.com\", \"formUrl\": null, \"phoneNumber\": null}, \"tradeName\": \"Dell Sp. z o.o.\"}}]}, \"trustedContent\": {\"paths\": [], \"productPaths\": []}, \"hasProtectedBrand\": true, \"aiCoCreatedContent\": {\"paths\": []}}','Komputery stacjonarne','Dell','3040 Micro i3-6GEN SSD HDMI WiFi W11H'),(1178,'5ca84c02-a667-419c-a885-d667a990130c',4610.00,12,'2024-10-11 08:57:41','{\"id\": \"5ca84c02-a667-419c-a885-d667a990130c\", \"name\": \"Komputer mini PC Dell 5010 4/120 GB\", \"price\": 4610, \"stock\": 12, \"images\": [{\"url\": \"https://a.allegroimg.com/original/29d488/0b5e25504812877be892b10475ba\"}, {\"url\": \"https://a.allegroimg.com/original/117b22/df64998744e0a4fd8d53a5d984eb\"}, {\"url\": \"https://a.allegroimg.com/original/11437e/ef2ad4894272ace6e0be1e66fa40\"}, {\"url\": \"https://a.allegroimg.com/original/118706/7d73306c4556905a09b01475907d\"}, {\"url\": \"https://a.allegroimg.com/original/110bb7/506f899c4dc4b306232d376e7d2f\"}, {\"url\": \"https://a.allegroimg.com/original/117494/2d0bce7441d7938eae0add0a9579\"}], \"category\": {\"id\": \"486\", \"path\": [{\"id\": \"954b95b6-43cf-4104-8354-dea4d9b10ddf\", \"name\": \"Allegro\"}, {\"id\": \"42540aec-367a-4e5e-b411-17c09b08e41f\", \"name\": \"Elektronika\"}, {\"id\": \"2\", \"name\": \"Komputery\"}, {\"id\": \"486\", \"name\": \"Komputery stacjonarne\"}], \"similar\": []}, \"createdAt\": \"2024-10-11T06:57:41.243Z\", \"parameters\": [{\"id\": \"248811\", \"name\": \"Marka\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"248811_1131529\"], \"valuesLabels\": [\"Dell\"]}, {\"id\": \"237206\", \"name\": \"Model\", \"unit\": null, \"values\": [\"5010\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"5010\"]}, {\"id\": \"206182\", \"name\": \"Seria\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"206182_1647173\"], \"valuesLabels\": [\"AMD Embedded G-Series\"]}, {\"id\": \"201725\", \"name\": \"Taktowanie bazowe procesora\", \"unit\": \"GHz\", \"values\": [\"1.40\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"1,40 GHz\"]}, {\"id\": \"201745\", \"name\": \"Typ pamięci RAM\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"201745_208889\"], \"valuesLabels\": [\"DDR3L\"]}, {\"id\": \"200941\", \"name\": \"Wielkość pamięci RAM\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"200941_2177\"], \"valuesLabels\": [\"4 GB\"]}, {\"id\": \"201769\", \"name\": \"Typ dysku twardego\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"201769_208985\"], \"valuesLabels\": [\"SSD\"]}, {\"id\": \"82\", \"name\": \"Pojemność dysku\", \"unit\": \"GB\", \"values\": [\"120\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"120 GB\"]}, {\"id\": \"201653\", \"name\": \"Typ komputera\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201653_208757\"], \"valuesLabels\": [\"komputer mini PC\"]}, {\"id\": \"224017\", \"name\": \"Kod producenta\", \"unit\": null, \"values\": [\"Z90D7\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"Z90D7\"]}, {\"id\": \"174\", \"name\": \"Typ napędu\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"174_256\"], \"valuesLabels\": [\"brak\"]}, {\"id\": \"201861\", \"name\": \"Komunikacja\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201861_32\"], \"valuesLabels\": [\"LAN 10/100/1000 Mbps\"]}, {\"id\": \"201865\", \"name\": \"System operacyjny\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201865_2048\"], \"valuesLabels\": [\"Linux\"]}, {\"id\": \"201817\", \"name\": \"Typ gniazda procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201817_209625\"], \"valuesLabels\": [\"wbudowany\"]}, {\"id\": \"201721\", \"name\": \"Taktowanie maksymalne procesora\", \"unit\": \"GHz\", \"values\": [\"1.40\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"1,40 GHz\"]}, {\"id\": \"4329\", \"name\": \"Liczba rdzeni procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"4329_2\"], \"valuesLabels\": [\"2\"]}, {\"id\": \"201777\", \"name\": \"Interfejs dysku twardego\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201777_1\"], \"valuesLabels\": [\"SATA III\"]}, {\"id\": \"201801\", \"name\": \"Złącza karty graficznej\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201801_1\"], \"valuesLabels\": [\"DisplayPort\"]}, {\"id\": \"218669\", \"name\": \"Certyfikaty zgodności\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"218669_1\"], \"valuesLabels\": [\"CE\"]}], \"description\": {\"sections\": [{\"items\": [{\"type\": \"TEXT\", \"content\": \"<p>Centrala do inteligentnego domu opartą o komputer Dell Wyse Z90D7 (odnowiony przez sprzedawcę) z 4&nbsp; GB ram&nbsp; i procesor 1,65 GHz - pasywne chłodzenie (bez wentylatora) wraz z lokalną Suplą.</p> <p><b>Od teraz wszystkie dane o Twoim Smart Home zostają tylko w Twoich rękach ! Kilkuset zadowolonych klientów.</b></p> <p>Home Assistant to otwarty system inteligentnego domu, który będzie skonfigurowany i gotowy do działania.</p> <p>Dołączona będzie pełna instrukcja działania całego systemu Smart Home, który dla Ciebie zbuduję. Dokumentacja zawiera wszystkie hasła i dane do konfiguracji oraz instrukcje w jaki sposób skonfigurować zainstalowane dodatki.</p> <p><b>Na komputerze jest zainstalowana jest lokalna instancja chmury SUPLA - sprzęt SUPLA działa po wifi nawet gdy nie działa&nbsp; dostęp do internetu.</b></p> <p>W Home Assistant skonfigurowane będą następujące integracje</p> <ul> <li>Speedteest - monitorująca prędkość łącza internetowego (wraz z wykresami)</li> <li><b>Cloudflared - zdalny dostęp do HA z domeną wystarczy wpisać własna konfigurację i działa. (jest to pokazane w dokumentacji)</b></li> <li>System monitor - pokazująca zużycie zasobów systemowych</li> <li>HACS - dodatek Home Assistant Community store umożliwiający instalację niestandardowych dodatków</li> <li>Lokalna chmura Supla - to samo co na stronie supla, ale u Ciebie w domu</li> <li>Automatyczny backup na dysk Googla - a w instrukcji jest informacja jak go skonfigurować</li> <li>Local Tuya (konfiguracja lokalna połączenia z urządzeniami Tuya)</li> <li>eWelink - wtyczka umożliwiająca podłączanie urządzeń Sonoff bez potrzeby zmiany oprogramowania (do działania wymaga dostępu do Internetu)</li> <li>Serwer plików Samba - do udostępniania zdjęć i filmów np na telewizorach</li> <li>dimmer slider - dodatek do GUI Home Assistant pozwalający w płynny sposób ustawiać poziom ściemniaczy / poziom rolet</li> <li>Harmonogram - dodatek umożliwiający ustawienie harmonogramów załączenia/ wyłączenia/ temperatury dla urządzeń.</li> <li>Urządzenia, które dodasz do lokalnej chmury Supla będą widoczne w home assistant</li> <li>Esphome - dodatek do programowania urządzeń oparty o ESP8266 oraz ESP32 - tworzenie urządzeń smart</li> </ul> <p>W zestawie otrzymasz sprzęt:</p> <ul> <li>Wykonana konfiguracja pod CC2652</li> <li>PDF z pełną dokumentacją systemu</li> <li>Zasilacz + kabel zasilający</li> </ul> <p><b>W zestawie brak podstawy</b></p> <p>Parametry komputera:</p> <ul> <li>Procesor:&nbsp;<b>Dual Core AMD T56N 1.65 GHz</b></li> <li>Pamięć RAM:&nbsp;<b>4GB DDR3</b></li> <li><b>Nowy</b> dysk SSD Goodram CL3 120 GB</li> <li>Porty:&nbsp;<b>1 x DVI / 1 x DP / 4 x USB 2.0 / 2x USB 3.0&nbsp; / 1 x 1000 Mb/s LAN</b></li> <li>Wymiary: 170 x 40x 185 [mm]</li> </ul> <p><b>Podczas uruchomienia systemu sprzęt pobiera 9 W</b></p> <p><b>Maksymalne zużycie prądu 15 W</b></p> <p>W dokumentacji znajdziesz:</p> <ul> <li>Jak zainstalować i skonfigurować Home Assistant z zigbee2mqtt</li> <li>Jak zainstalować Home Assistant</li> <li>Jak zainstalować HACS umożliwiający dodawanie niestandarodywch dodatków do Home Assistant</li> <li>Jak zainstalować i skonfigurować dongle zigbee i zigbee2mqtt</li> <li>Jak dodawać i konfigurować urządzenia Zibgee</li> <li>Jak skonfigurować google cloud backup</li> <li>Trochę informacji o Zigbee oraz poszerzaniu zasięgu.</li> </ul>\"}]}, {\"items\": [{\"url\": \"https://a.allegroimg.com/original/117494/2d0bce7441d7938eae0add0a9579\", \"type\": \"IMAGE\"}]}]}, \"publication\": {\"status\": \"LISTED\"}, \"productSafety\": {\"safetyInformation\": {\"type\": \"TEXT\", \"description\": \"Lista ostrzeżeń dotyczących bezpieczeństwa komputerów stacjonarnych oparta o wymagania Rozporządzenia (UE) 2023/988 w sprawie ogólnego bezpieczeństwa produktów (GPSR)\\n\\n*   Ryzyko porażenia prądem:\\n\\n    *   Upewnij się, że komputer jest podłączony do sprawnego gniazdka z uziemieniem.\\n    *   Nie dotykaj wtyczki ani kabla mokrymi rękami.\\n    *   Unikaj używania komputera w miejscach o dużej wilgotności.\\n*   Ryzyko przegrzania:\\n\\n    *   Zapewnij odpowiednią wentylację, zachowując co najmniej 5 cm wolnej przestrzeni wokół komputera.\\n    *   Nie blokuj otworów wentylacyjnych.\\n*   Ryzyko pożaru:\\n\\n    *   Używaj wyłącznie oryginalnych ładowarek i akcesoriów zalecanych przez producenta.\\n    *   Nie pozostawiaj komputera włączonego bez nadzoru w pobliżu materiałów łatwopalnych.\\n*   Ryzyko uszkodzeń ciała:\\n\\n    *   Używaj komputera na stabilnej powierzchni, aby zminimalizować ryzyko upadku.\\n*   Zagrożenia w wilgotnym środowisku:\\n\\n    *   Nie używaj komputera na zewnątrz podczas deszczu ani w miejscach o dużej wilgotności.\\n    *   W przypadku zalania komputera natychmiast odłącz go od źródła zasilania i skontaktuj się z serwisem.\\n*   Zagrożenia w wysokich temperaturach:\\n\\n    *   Nie eksponuj komputera na bezpośrednie działanie promieni słonecznych.\\n    *   Unikaj korzystania z komputera w temperaturach przekraczających zalecany zakres (zwykle 5-35°C).\\n*   Ryzyko uszkodzenia podczas czyszczenia:\\n\\n    *   Przed czyszczeniem odłącz komputer od zasilania i użyj miękkiej, lekko wilgotnej ściereczki.\\n    *   Unikaj stosowania silnych detergentów mogących uszkodzić powierzchnię komputera.\\n*   Ostrożność podczas wymiany akcesoriów:\\n\\n    *   Korzystaj wyłącznie z akcesoriów zalecanych przez producenta.\\n    *   W przypadku wymiany baterii, przestrzegaj zaleceń producenta i nie wystawiaj baterii na działanie wysokich temperatur.\\n*   Zagrożenia związane z użytkowaniem baterii:\\n\\n    *   Unikaj uszkodzenia baterii przez uderzenia lub jej przebicie.\\n    *   Jeśli bateria się przegrzewa lub puchnie, natychmiast przerwij użytkowanie komputera.\\n*   Ostrzeżenia dotyczące dzieci:\\n\\n    *   Trzymaj kable zasilające poza zasięgiem dzieci.\\n    *   Upewnij się, że dzieci nie bawią się komputerem ani akcesoriami, które mogą być niebezpieczne.\"}, \"responsibleProducers\": [{\"id\": \"5a19885c-b071-408d-9c12-19f29b22e854\", \"name\": \"Dell.\", \"producerData\": {\"address\": {\"city\": \"Warszawa\", \"street\": \"ul. Domaniewska 48\", \"postalCode\": \"02-672\", \"countryCode\": \"PL\"}, \"contact\": {\"email\": \"pl_customercare@dell.com\", \"formUrl\": null, \"phoneNumber\": null}, \"tradeName\": \"Dell Sp. z o.o.\"}}]}, \"trustedContent\": {\"paths\": [], \"productPaths\": []}, \"hasProtectedBrand\": true, \"aiCoCreatedContent\": {\"paths\": []}}','Komputery stacjonarne','Dell','5010'),(1179,'04cf5219-0c0c-48fc-8af6-915bda9d6281',3390.00,6,'2026-02-14 04:37:10','{\"id\": \"04cf5219-0c0c-48fc-8af6-915bda9d6281\", \"name\": \"Komputer stacjonarny Dell OptiPlex i7 16 GB 500 GB SSD Windows 11 Pro\", \"price\": 3390, \"stock\": 6, \"images\": [{\"url\": \"https://a.allegroimg.com/original/290d19/64b7ee2c46cfa7a275ab558bae58\"}, {\"url\": \"https://a.allegroimg.com/original/111544/00404c854ec29f341201c70be135\"}, {\"url\": \"https://a.allegroimg.com/original/11b03c/4f0ce60e42e1bc7ad59f9f692885\"}, {\"url\": \"https://a.allegroimg.com/original/11021a/8552e8704ec38ee9bf21d309b223\"}, {\"url\": \"https://a.allegroimg.com/original/11e1c0/55eb214348ed8c763c5a92ad102b\"}, {\"url\": \"https://a.allegroimg.com/original/114022/dc5d2da645f9b077530957fdf702\"}, {\"url\": \"https://a.allegroimg.com/original/11f15b/3fd532404ad390442e2bffbc1edb\"}, {\"url\": \"https://a.allegroimg.com/original/11c3bf/987b29f34b1fbc75a23e7428a00d\"}, {\"url\": \"https://a.allegroimg.com/original/1189d9/05ae93164b68bbdd6d37d18fd83b\"}, {\"url\": \"https://a.allegroimg.com/original/11bd3d/e9a724c34af39ca5e2e2006e06ec\"}, {\"url\": \"https://a.allegroimg.com/original/11749e/2cddfbba491da9bd0cef8b238fd3\"}, {\"url\": \"https://a.allegroimg.com/original/113276/5cbf528e4870bfd002e853949ec1\"}, {\"url\": \"https://a.allegroimg.com/original/113988/dfc42deb4c0e9dc3a35fa27c4079\"}, {\"url\": \"https://a.allegroimg.com/original/11aa60/3cd2483a4f8691cc12488dc6dd2b\"}, {\"url\": \"https://a.allegroimg.com/original/113ab4/555709e14fdcb1754fa9254221ae\"}], \"category\": {\"id\": \"486\", \"path\": [{\"id\": \"954b95b6-43cf-410