g\", \"values\": [\"1.30\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"1,30 kg\"]}, {\"id\": \"174\", \"name\": \"Typ napędu\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"174_256\"], \"valuesLabels\": [\"brak\"]}, {\"id\": \"201841\", \"name\": \"Moc zasilacza\", \"unit\": \"W\", \"values\": [\"65\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"65 W\"]}, {\"id\": \"201861\", \"name\": \"Komunikacja\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201861_64\"], \"valuesLabels\": [\"LAN 10/100 Mbps\"]}, {\"id\": \"201865\", \"name\": \"System operacyjny\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201865_8192\"], \"valuesLabels\": [\"brak systemu\"]}, {\"id\": \"219805\", \"name\": \"Model procesora\", \"unit\": null, \"values\": [\"i3-7100T\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"i3-7100T\"]}, {\"id\": \"249393\", \"name\": \"Generacja procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"249393_1188968\"], \"valuesLabels\": [\"7\"]}, {\"id\": \"201817\", \"name\": \"Typ gniazda procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"201817_209581\"], \"valuesLabels\": [\"Socket 1151\"]}, {\"id\": \"201721\", \"name\": \"Taktowanie maksymalne procesora\", \"unit\": \"GHz\", \"values\": [\"3.40\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"3,40 GHz\"]}, {\"id\": \"201729\", \"name\": \"Pamięć podręczna procesora\", \"unit\": \"MB\", \"values\": [\"3.00\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"3,00 MB\"]}, {\"id\": \"4329\", \"name\": \"Liczba rdzeni procesora\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesIds\": [\"4329_2\"], \"values