"values\": null, \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesIds\": [\"206966_65536\", \"206966_32768\", \"206966_134217728\", \"206966_8192\", \"206966_268435456\", \"206966_4096\", \"206966_2048\"], \"valuesLabels\": [\"2133\", \"2400\", \"2666\", \"2800\", \"2933\", \"3000\", \"3200\"]}, {\"id\": \"206974\", \"name\": \"Architektura wielokanałowa pamięci RAM\", \"unit\": null, \"values\": null, \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesIds\": [\"206974_228966\"], \"valuesLabels\": [\"dual-channel\"]}, {\"id\": \"206926\", \"name\": \"Obsługa wielu kart graficznych\", \"unit\": null, \"values\": null, \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesIds\": [\"206926_4\"], \"valuesLabels\": [\"nie obsługuje\"]}, {\"id\": \"206894\", \"name\": \"Dual BIOS\", \"unit\": null, \"values\": null, \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesIds\": [\"206894_228806\"], \"valuesLabels\": [\"tak\"]}, {\"id\": \"219829\", \"name\": \"Kanały audio\", \"unit\": null, \"values\": [\"7,1\"], \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesLabels\": [\"7,1\"]}, {\"id\": \"206902\", \"name\": \"Łączenie dysków\", \"unit\": null, \"values\": null, \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesIds\": [\"206902_2\", \"206902_4\", \"206902_512\"], \"valuesLabels\": [\"RAID 0\", \"RAID 1\", \"RAID 1+0 (10)\"]}, {\"id\": \"206978\", \"name\": \"Gniazda rozszerzeń i złącza napędów\", \"unit\": null, \"values\": null, \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesIds\": [\"206978_64\"], \"valuesLabels\": [\"PCIe 2.0 x1\"]}, {\"id\": \"206986\", \"name\": \"Złącza na panelu tylnym\", \"unit\": null, \"values\": null, \"options\": {\"isTrusted\": true, \"identifiesProduct\": false}, \"valuesIds\": [\"206986_64\"], \"valuesLabels\": [\"HDMI\"]}, {\"id\": \"206990\", \"name\": \"Dodatkowe elementy\