: []}, \"trustedContent\": {\"paths\": [], \"productPaths\": []}, \"hasProtectedBrand\": false, \"aiCoCreatedContent\": {\"paths\": []}}','Pamięć RAM',NULL,'PC5-38400'),(1824,'4b7a4a0f-9e28-43d1-adf0-c9f7bc991c18',3609.00,46,'2024-09-01 19:43:23','{\"id\": \"4b7a4a0f-9e28-43d1-adf0-c9f7bc991c18\", \"name\": \"LENOVO L-IG41M MOTHERBOARD 71Y6942 s.775 DDR2 PCI PCIe ThinkCentre\", \"price\": 3609, \"stock\": 46, \"images\": [{\"url\": \"https://a.allegroimg.com/original/11799e/3ca5e26f43108092c62c8e874d86\"}], \"category\": {\"id\": \"4228\", \"path\": [{\"id\": \"954b95b6-43cf-4104-8354-dea4d9b10ddf\", \"name\": \"Allegro\"}, {\"id\": \"42540aec-367a-4e5e-b411-17c09b08e41f\", \"name\": \"Elektronika\"}, {\"id\": \"2\", \"name\": \"Komputery\"}, {\"id\": \"4226\", \"name\": \"Podzespoły komputerowe\"}, {\"id\": \"4228\", \"name\": \"Płyty główne\"}], \"similar\": []}, \"createdAt\": \"2024-09-01T17:43:23.179Z\", \"parameters\": [{\"id\": \"237206\", \"name\": \"Model\", \"unit\": null, \"values\": [\"L-IG41M\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"L-IG41M\"]}, {\"id\": \"248914\", \"name\": \"Producent\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": true}, \"valuesIds\": [\"248914_1987925\"], \"valuesLabels\": [\"Lenovo\"]}, {\"id\": \"225693\", \"name\": \"EAN (GTIN)\", \"unit\": null, \"values\": [\"4250393798251\"], \"options\": {\"isGTIN\": true, \"identifiesProduct\": true}, \"valuesLabels\": [\"4250393798251\"]}, {\"id\": \"219825\", \"name\": \"Chipset\", \"unit\": null, \"values\": [\"Intel G41 Express\"], \"options\": {\"identifiesProduct\": true}, \"valuesLabels\": [\"Intel G41 Express\"]}, {\"id\": \"224017\", \"name\": \"Kod producenta\", \"unit\": null, \"values\": [\"L-IG41M\"], \"options\": {\"identifiesProduct\": false}, \"valuesLabels\": [\"L-IG41M\"]}, {\"id\": \"206754\", \"name\": \"Obsługiwane procesory\", \"unit\": null, \"values\": null, \"options\": {\"identifiesProduct\": false}, \"valuesId